const cats=['업무 경험','독서','뉴스','관심사'],folders=['01-HR','02-독서','03-뉴스','04-관심사'];
let notes=[...publishedNotes],category='업무 경험',tag='',companyFilter='',authorFilter='',ratingFilter='',sortBy='latest',page=1,root=null,example=true;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function companyName(n){return n.company||(n.body.match(/^\*\*소속:\*\*\s*([^\r\n]+)/m)?.[1]||'').trim()}
function ratingValue(n){return (n.rating?.match(/[★⭐]/g)||[]).length}
function render(){for(const sel of ['#nav','#tabs'])$(sel).innerHTML=cats.map((c,i)=>`<button data-cat="${c}" class="${category===c?'active':''}">${sel==='#nav'?['▤　','▥　','▧　','✳　'][i]:''}${c}${sel==='#nav'?`<span>${notes.filter(n=>n.category===c).length}</span>`:''}</button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;companyFilter='';tag='';authorFilter='';ratingFilter='';page=1;render()});
const base=notes.filter(n=>n.category===category),tags=[...new Set(base.flatMap(n=>n.tags))];$('#tags').innerHTML=['',...tags].map(t=>`<button class="${tag===t?'active':''}" data-tag="${esc(t)}">${t?'# '+esc(t):'모든 태그'}</button>`).join('');document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{tag=b.dataset.tag;page=1;render()});
$('#tags').hidden=category==='업무 경험';
const isReading=category==='독서';
$('#company-filter-label').hidden=category!=='업무 경험';
const companies=[...new Set(base.map(companyName).filter(Boolean))].sort();
$('#company-filter').innerHTML='<option value="">전체 회사</option>'+companies.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');
$('#company-filter').value=companyFilter;
$('#author-filter-label').hidden=!isReading;$('#rating-filter-label').hidden=!isReading;
const authors=[...new Set(base.map(n=>n.author).filter(Boolean))].sort();
$('#author-filter').innerHTML='<option value="">전체 저자</option>'+authors.map(a=>`<option value="${esc(a)}">${esc(a)}</option>`).join('');
$('#author-filter').value=authorFilter;$('#rating-filter').value=ratingFilter;
const q=$('#search').value.toLowerCase(),list=base.filter(n=>(category!=='업무 경험'||!companyFilter||companyName(n)===companyFilter)&&(!tag||n.tags.includes(tag))&&(!isReading||!authorFilter||n.author===authorFilter)&&(!isReading||!ratingFilter||ratingValue(n)===Number(ratingFilter))&&[n.title,n.body,...n.tags].join(' ').toLowerCase().includes(q)).sort((a,b)=>sortBy==='oldest'?a.date.localeCompare(b.date):sortBy==='rating'?(ratingValue(b)-ratingValue(a)||b.date.localeCompare(a.date)):b.date.localeCompare(a.date));
$('#heading').firstChild.textContent=category+' ';$('#count').textContent=list.length;
const totalPages=Math.max(1,Math.ceil(list.length/10));page=Math.min(page,totalPages);
$('#grid').innerHTML=list.slice((page-1)*10,page*10).map(n=>{const i=Math.max(0,cats.indexOf(n.category));return `<button class="card${n.category==='업무 경험'?' experience-card':''}" data-id="${esc(n.id)}">${n.category==='업무 경험'?'':`<div class="cover c${i}">${n.cover?`<img src="${esc(n.cover)}" alt="${esc(n.title)} 책 표지" loading="lazy">`:`<strong>${['People & possibilities.','Between the pages.','A changing world.','Stay curious.'][i]}</strong><span>${['◫','▥','↗','✳'][i]}</span>`}</div>`}<div class="cardbody"><div class="meta"><span>${esc(n.category)}${n.id.startsWith('sample')?' · EXAMPLE':''}${n.author?' · '+esc(n.author)+' 저':''}${n.rating?' <span class="book-rating" aria-label="별점 '+ratingValue(n)+'점">'+esc(n.rating)+'</span>':''}</span>${n.category==='업무 경험'?'':`<span>${esc(n.date)}</span>`}</div><div class="title-line"><h3>${esc(n.title)}</h3><div class="cardtags">${n.tags.map(t=>'#'+esc(t)).join('　')}</div></div><p>${esc(n.summary||n.body)}</p></div></button>`}).join('')||'<div class="empty">아직 기록이 없습니다.</div>';
document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openNote(notes.find(n=>n.id===b.dataset.id)));
$('#pagination').innerHTML=`<button data-page="${page-1}" ${page===1?'disabled':''} aria-label="이전 페이지">← 이전</button>${Array.from({length:totalPages},(_,i)=>`<button data-page="${i+1}" ${page===i+1?'aria-current="page" class="active"':''}>${i+1}</button>`).join('')}<button data-page="${page+1}" ${page===totalPages?'disabled':''} aria-label="다음 페이지">다음 →</button>`;
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);render();$('#heading').scrollIntoView({behavior:'smooth',block:'start'})});}

function sourceLink(n){try{const u=new URL(n.sourceUrl);if(!['http:','https:'].includes(u.protocol))return '';const label=n.category==='독서'?'책 정보 보기':n.category==='뉴스'?'기사 원문 보기':'관련 원본 보기';return `<p class="source-link"><a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${label} ↗ <small>${esc(u.hostname)}</small></a></p>`}catch{return ''}}
function experienceContent(n){
if(n.category!=='업무 경험')return '';
const body=n.body.replace(/\r\n/g,'\n'),headings=[...body.matchAll(/^###\s+(상황|과제|행동|결과)\s*\((Situation|Task|Action|Result)\)\s*$/gm)];
if(headings.length!==4||headings.map(h=>h[2]).join()!=='Situation,Task,Action,Result')return '';
const result=body.match(/^\*\*핵심 성과:\*\*\s*([\s\S]*)$/m),end=result?result.index:body.length;
const inline=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
const blocks=s=>s.trim().split(/\n\s*\n/).filter(Boolean).map(p=>{const lines=p.split('\n');return lines.every(l=>/^[-*]\s/.test(l))?'<ul>'+lines.map(l=>'<li>'+inline(l.replace(/^[-*]\s+/,''))+'</li>').join('')+'</ul>':'<p>'+inline(p).replace(/\n/g,'<br>')+'</p>'}).join('');
const clean=s=>s.replace(/\n*---\s*$/,'').trim();
return `<div class="experience-intro">${blocks(body.slice(0,headings[0].index).replace(/^#\s+.+\n/,''))}</div><div class="star-grid">${headings.map((h,i)=>`<section class="star-section"><h3><span>${'STAR'[i]}</span>${h[1]}<small>${h[2]}</small></h3>${blocks(clean(body.slice(h.index+h[0].length,i<3?headings[i+1].index:end)))}</section>`).join('')}</div>${result?`<section class="star-outcome"><h3>핵심 성과</h3>${blocks(result[1])}</section>`:''}`;
}
function openNote(n){const experience=experienceContent(n);$('#detail').classList.toggle('experience-detail',Boolean(experience));$('#detailbody').innerHTML=`<div class="eyebrow">${esc(n.category)}</div><h2>${esc(n.title)}</h2><p class="detail-meta">${[n.category==='업무 경험'?'':n.date,n.author?n.author+' 저':'',n.rating,n.tags.join(' / ')].filter(Boolean).map(esc).join(' · ')}</p>${sourceLink(n)}${experience||`<div class="note-body${n.html?' article-body':''}">${n.html||esc(n.body)}</div>`}`;$('#detail').showModal()}
function parse(text,path){const m=text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n/),meta={};if(m)for(const l of m[1].split(/\r?\n/)){const p=l.indexOf(':');if(p>0)meta[l.slice(0,p).trim()]=l.slice(p+1).trim()}let body=m?text.slice(m[0].length):text;const inferred=folders.findIndex(f=>f&&path.includes(f));return{id:path,title:meta.title||body.match(/^#\s+(.+)$/m)?.[1]||path.split('/').pop().replace(/\.(md|txt)$/i,''),category:meta.category==='HR 포트폴리오'?'업무 경험':cats.includes(meta.category)?meta.category:cats[inferred>=0?inferred:3],date:/^\d{4}-\d{2}-\d{2}$/.test(meta.date)?meta.date:'',tags:(meta.tags||'').split(',').map(t=>t.trim()).filter(Boolean),sourceUrl:meta.sourceUrl||meta.url||'',body:body.replace(/^#\s+.+\r?\n/,'').trim()}}
async function readFolder(){const found=[];async function walk(dir,prefix=''){for await(const [name,h]of dir.entries()){if(name.startsWith('.'))continue;if(h.kind==='directory')await walk(h,prefix+name+'/');else if(/\.(md|txt)$/i.test(name)){const f=await h.getFile();if(f.size<2000000)found.push(parse(await f.text(),prefix+name))}}}await walk(root);notes=found;example=false;render()}
$('#company-filter').onchange=e=>{companyFilter=e.target.value;page=1;render()};
$('#author-filter').onchange=e=>{authorFilter=e.target.value;page=1;render()};
$('#rating-filter').onchange=e=>{ratingFilter=e.target.value;page=1;render()};
$('#reset-filters').onclick=()=>{companyFilter='';authorFilter='';ratingFilter='';sortBy='latest';tag='';$('#search').value='';page=1;render()};
$('#search').oninput=()=>{page=1;render()};document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#new').onclick=()=>{$('#form').reset();$('#form [name=date]').value=new Date().toLocaleDateString('sv-SE');$('#saveinfo').textContent=root?'연결한 폴더에 Markdown 파일로 저장합니다.':'Markdown 파일을 다운로드합니다. 나의 아카이브의 해당 분류 폴더에 저장하세요.';$('#editor').showModal()};
$('#form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),filename=v.date+'-'+v.title.replace(/[<>:"/\\|?*\x00-\x1f]/g,'-').slice(0,90)+'.md',text=`---\ntitle: ${v.title}\ncategory: ${v.category}\ndate: ${v.date}\ntags: ${v.tags}\nurl: ${v.url}\n---\n\n${v.body}\n`;try{if(root){const d=await root.getDirectoryHandle(folders[cats.indexOf(v.category)],{create:true});try{await d.getFileHandle(filename);alert('같은 날짜와 제목의 파일이 있습니다. 제목을 변경해 주세요.');return}catch(err){if(err.name!=='NotFoundError')throw err}const f=await d.getFileHandle(filename,{create:true}),w=await f.createWritable();await w.write(text);await w.close();await readFolder()}else{const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);if(example)notes=[];example=false;notes.push(parse(text,filename));render()}$('#editor').close()}catch(err){alert('저장하지 못했습니다: '+err.message)}};

function showHelp(extra=''){$('#detailbody').innerHTML=`<div class="eyebrow">LOCAL FIRST</div><h2>내 컴퓨터에서 관리하는 기록</h2>${extra?'<p>'+esc(extra)+'</p>':''}<div class="note-body">1. 제공된 ‘나의 아카이브’ 폴더를 사용하세요.\n2. ‘로컬 폴더 연결’에서 해당 폴더를 선택하고 권한을 허용하세요. Chrome·Edge 데스크톱을 권장합니다.\n3. ‘새 기록’으로 작성하면 분류별 폴더에 .md 파일로 저장됩니다.\n4. 외부 편집기로 수정한 뒤 ‘폴더 새로고침’을 누르세요.\n\n01-HR / 02-독서 / 03-뉴스 / 04-관심사\n\n폴더 연결은 브라우저의 권한을 사용하며 다시 방문하면 재연결이 필요합니다. 로컬 기록은 서버에 업로드되지 않습니다. 파일 가져오기는 현재 탭에서만 유지되므로 원본 파일을 보관하세요. 파일 다운로드 방식에서는 다운로드한 파일을 직접 분류 폴더에 옮겨주세요.</div>`;$('#detail').showModal()}render();

const linkedNote=notes.find(n=>n.id===location.hash.slice(1));if(linkedNote){category=linkedNote.category;render();openNote(linkedNote);}
